class ProductRepo:
    def __init__(self):
        self.store = {}; self.cache = {}
    def get(self, pid):
        if pid in self.cache: return self.cache[pid]
        self.cache[pid] = self.store.get(pid); return self.cache[pid]
    def update(self, pid, price):
        self.store[pid] = price
